entity Prob_5_60_vhdl is	port  (y_out: buffer bit_vector (3 downto 0); Run, clk, reset_b: in bit);end Prob_5_60_vhdl;architecture Behavioral of Prob_5_60_vhdl isbeginprocess (clk) begin	if clk'event and clk = '1'  then		if (reset_b = '0') then y_out <= "0000";		elsif  (Run = '1')  then			case (y_out) is				when "0000" =>	y_out <= "0001";				when "0001" =>	y_out <= "0010";				when "0010" =>	y_out <= "0011";				when "0011" =>	y_out <= "0100";				when "0100" =>	y_out <= "0101";				when "0101" =>	y_out <= "0110";				when "0110" =>	y_out <= "0111";				when "0111" =>	y_out <= "1000";				when "1010" =>	y_out <= "1001";				when "1001" =>	y_out <= "0000";				when others =>	y_out <= "0001";			end case;
		end if;	end if;end process;end Behavioral;